type LibraryScanners []LibraryScanner

// Find returns libraries matching a lockfile path and name.
func (lss LibraryScanners) Find(path, name string) map[string]types.Library {
	filtered := map[string]types.Library{}
	for _, ls := range lss {
		if ls.Path != path {
			continue
		}
		for _, lib := range ls.Libs {
			if lib.Name == name {
				filtered[ls.Path] = lib
				break
			}
		}
	}
	return filtered
}

// LibraryScanner has libraries information
type LibraryScanner struct {
	Path string
	Libs []types.Library
}

// Scan : scan target library
func (s LibraryScanner) Scan() ([]VulnInfo, error) {
	scanner, err := newLibraryDriver(filepath.Base(s.Path))
	if err != nil {
		return nil, err
	}

	var vulnerabilities = []VulnInfo{}
	for _, pkg := range s.Libs {
		v, err := version.NewVersion(pkg.Version)
		if err != nil {
			util.Log.Debugf("new version cant detected %s@%s", pkg.Name, pkg.Version)
			continue
		}

